// ReviewSection.jsx
import React, { useState } from 'react';
import StarRating from './StarRating';

const ReviewSection = () => {
  // Local state for reviews, rating input, and comment
  const [reviews, setReviews] = useState([]);
  const [rating, setRating] = useState(0);
  const [comment, setComment] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    // Basic validation: both rating and comment should be provided
    if (rating === 0 || comment.trim() === '') {
      alert('Please provide both a rating and a comment.');
      return;
    }

    const newReview = {
      id: Date.now(), // simple unique id using timestamp
      rating,
      comment,
    };

    // Add the new review to the list
    setReviews([...reviews, newReview]);

    // Clear the form fields
    setRating(0);
    setComment('');
  };

  return (
    <div className="review-section">
      <h3>Customer Reviews</h3>
      <form onSubmit={handleSubmit}>
        <div>
          <label>Rating: </label>
          {/* Editable StarRating component */}
          <StarRating rating={rating} setRating={setRating} editable={true} />
        </div>
        <div>
          <label htmlFor="review-comment">Comment: </label>
          <textarea
            id="review-comment"
            value={comment}
            onChange={(e) => setComment(e.target.value)}
            placeholder="Enter your review here"
            rows="4"
            cols="50"
            required
          />
        </div>
        <button type="submit">Submit Review</button>
      </form>

      <div className="review-list">
        <h4>All Reviews</h4>
        {reviews.length === 0 ? (
          <p>No reviews yet. Be the first to review!</p>
        ) : (
          reviews.map((review) => (
            <div key={review.id} className="review-item" style={{ borderBottom: '1px solid #ccc', padding: '10px 0' }}>
              {/* Non-editable StarRating display */}
              <StarRating rating={review.rating} editable={false} />
              <p>{review.comment}</p>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default ReviewSection;
